-- Ecommerce learning platform: MySQL 8.0.16+
-- Create an empty ecommerce_platform schema before importing. Do not run repeatedly over populated data.

-- Identity and back-office access control. Passwords must be encoded by Spring Security (BCrypt/Argon2).
CREATE TABLE app_users (
 user_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 email VARCHAR(254) NOT NULL, password_hash VARCHAR(255) NULL,
 display_name VARCHAR(160) NOT NULL, phone VARCHAR(30),
 user_status ENUM('invited','active','locked','disabled') NOT NULL DEFAULT 'invited',
 email_verified_at DATETIME NULL, last_login_at DATETIME NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_app_users_email(email)
) ENGINE=InnoDB;
CREATE TABLE roles (role_id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, description VARCHAR(255));
CREATE TABLE permissions (permission_id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255));
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id SMALLINT UNSIGNED NOT NULL, granted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES app_users(user_id), FOREIGN KEY(role_id) REFERENCES roles(role_id));
CREATE TABLE role_permissions (role_id SMALLINT UNSIGNED NOT NULL, permission_id SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(role_id), FOREIGN KEY(permission_id) REFERENCES permissions(permission_id));
CREATE TABLE employees (employee_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, employee_code VARCHAR(30) NOT NULL UNIQUE, department VARCHAR(80), job_title VARCHAR(100), hired_at DATE NOT NULL, employment_status ENUM('active','leave','terminated') NOT NULL DEFAULT 'active', FOREIGN KEY(user_id) REFERENCES app_users(user_id));
CREATE TABLE customers (customer_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL UNIQUE, customer_number VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, birth_date DATE NULL, marketing_opt_in BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, customer_status ENUM('active','inactive','blocked') NOT NULL DEFAULT 'active', FOREIGN KEY(user_id) REFERENCES app_users(user_id));
CREATE TABLE customer_addresses (address_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, label VARCHAR(50), recipient_name VARCHAR(160) NOT NULL, phone VARCHAR(30), line1 VARCHAR(200) NOT NULL, line2 VARCHAR(200), ward VARCHAR(100), district VARCHAR(100), city VARCHAR(100) NOT NULL, region VARCHAR(100), postal_code VARCHAR(20), country_code CHAR(2) NOT NULL, is_default_shipping BOOLEAN NOT NULL DEFAULT FALSE, is_default_billing BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE brands (brand_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, slug VARCHAR(140) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE categories (category_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_category_id INT UNSIGNED NULL, name VARCHAR(100) NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE, description VARCHAR(500), sort_order INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(parent_category_id) REFERENCES categories(category_id));
CREATE TABLE products (product_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, brand_id INT UNSIGNED NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, description MEDIUMTEXT, product_status ENUM('draft','active','archived') NOT NULL DEFAULT 'draft', tax_class VARCHAR(40) NOT NULL DEFAULT 'standard', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(brand_id) REFERENCES brands(brand_id), FULLTEXT KEY ft_products_name_description(name,description));
CREATE TABLE product_categories (product_id BIGINT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(product_id,category_id), FOREIGN KEY(product_id) REFERENCES products(product_id), FOREIGN KEY(category_id) REFERENCES categories(category_id));
CREATE TABLE product_media (media_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, media_url VARCHAR(1000) NOT NULL, alt_text VARCHAR(255), sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0, is_primary BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE product_variants (variant_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, sku VARCHAR(50) NOT NULL UNIQUE, variant_name VARCHAR(160) NOT NULL, attributes JSON NULL, barcode VARCHAR(80) UNIQUE, price DECIMAL(12,2) NOT NULL, cost DECIMAL(12,2) NOT NULL DEFAULT 0, weight_kg DECIMAL(9,3), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(price>=0 AND cost>=0), FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE suppliers (supplier_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_code VARCHAR(30) NOT NULL UNIQUE, company_name VARCHAR(180) NOT NULL, contact_name VARCHAR(120), email VARCHAR(254), phone VARCHAR(30), country_code CHAR(2), payment_terms_days SMALLINT UNSIGNED NOT NULL DEFAULT 30, supplier_status ENUM('active','inactive') NOT NULL DEFAULT 'active');
CREATE TABLE supplier_variants (supplier_id INT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, supplier_sku VARCHAR(80), unit_cost DECIMAL(12,2) NOT NULL, lead_time_days SMALLINT UNSIGNED NOT NULL DEFAULT 0, is_preferred BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(supplier_id,variant_id), CHECK(unit_cost>=0), FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id), FOREIGN KEY(variant_id) REFERENCES product_variants(variant_id));
CREATE TABLE warehouses (warehouse_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, line1 VARCHAR(200), city VARCHAR(100) NOT NULL, region VARCHAR(100), country_code CHAR(2) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE inventory (warehouse_id INT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, on_hand INT NOT NULL DEFAULT 0, reserved INT NOT NULL DEFAULT 0, reorder_point INT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(warehouse_id,variant_id), CHECK(on_hand>=0 AND reserved>=0 AND reserved<=on_hand), FOREIGN KEY(warehouse_id) REFERENCES warehouses(warehouse_id), FOREIGN KEY(variant_id) REFERENCES product_variants(variant_id));
CREATE TABLE stock_movements (movement_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, warehouse_id INT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, movement_type ENUM('receipt','reservation','release','shipment','return','adjustment','transfer_in','transfer_out') NOT NULL, quantity_delta INT NOT NULL, reserved_delta INT NOT NULL DEFAULT 0, reference_type VARCHAR(40), reference_id BIGINT UNSIGNED, performed_by BIGINT UNSIGNED NULL, note VARCHAR(500), occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(warehouse_id) REFERENCES warehouses(warehouse_id), FOREIGN KEY(variant_id) REFERENCES product_variants(variant_id), FOREIGN KEY(performed_by) REFERENCES app_users(user_id), KEY ix_stock_variant_date(variant_id,occurred_at));
CREATE TABLE carts (cart_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NULL, session_key VARCHAR(100) NULL UNIQUE, cart_status ENUM('active','converted','abandoned') NOT NULL DEFAULT 'active', currency CHAR(3) NOT NULL DEFAULT 'USD', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE cart_items (cart_item_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cart_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, added_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_cart_variant(cart_id,variant_id), CHECK(quantity>0), FOREIGN KEY(cart_id) REFERENCES carts(cart_id), FOREIGN KEY(variant_id) REFERENCES product_variants(variant_id));
CREATE TABLE coupons (coupon_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, description VARCHAR(255), discount_type ENUM('percent','fixed') NOT NULL, discount_value DECIMAL(12,2) NOT NULL, minimum_subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, max_discount DECIMAL(12,2), starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, max_redemptions INT UNSIGNED, per_customer_limit SMALLINT UNSIGNED NOT NULL DEFAULT 1, is_active BOOLEAN NOT NULL DEFAULT TRUE, CHECK(discount_value>0 AND minimum_subtotal>=0 AND ends_at>starts_at));
CREATE TABLE orders (order_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(32) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NULL, placed_by_user_id BIGINT UNSIGNED NULL, source ENUM('web','admin','phone','marketplace') NOT NULL DEFAULT 'web', order_status ENUM('pending','confirmed','processing','partially_shipped','shipped','completed','cancelled','partially_returned','returned') NOT NULL DEFAULT 'pending', payment_status ENUM('unpaid','authorized','partially_paid','paid','partially_refunded','refunded','failed') NOT NULL DEFAULT 'unpaid', fulfillment_status ENUM('unfulfilled','partially_fulfilled','fulfilled','returned') NOT NULL DEFAULT 'unfulfilled', currency CHAR(3) NOT NULL DEFAULT 'USD', source_cart_id BIGINT UNSIGNED NULL, customer_email VARCHAR(254) NOT NULL, customer_name VARCHAR(160) NOT NULL, customer_phone VARCHAR(30), subtotal DECIMAL(12,2) NOT NULL, discount_total DECIMAL(12,2) NOT NULL DEFAULT 0, shipping_total DECIMAL(12,2) NOT NULL DEFAULT 0, tax_total DECIMAL(12,2) NOT NULL DEFAULT 0, grand_total DECIMAL(12,2) NOT NULL, customer_note VARCHAR(1000), internal_note VARCHAR(1000), placed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK(subtotal>=0 AND discount_total>=0 AND shipping_total>=0 AND tax_total>=0 AND grand_total>=0), FOREIGN KEY(customer_id) REFERENCES customers(customer_id), FOREIGN KEY(placed_by_user_id) REFERENCES app_users(user_id), UNIQUE KEY uq_orders_source_cart(source_cart_id), FOREIGN KEY(source_cart_id) REFERENCES carts(cart_id), KEY ix_orders_customer_date(customer_id,placed_at), KEY ix_orders_status_date(order_status,placed_at));
CREATE TABLE order_addresses (order_address_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, address_type ENUM('billing','shipping') NOT NULL, recipient_name VARCHAR(160) NOT NULL, phone VARCHAR(30), line1 VARCHAR(200) NOT NULL, line2 VARCHAR(200), ward VARCHAR(100), district VARCHAR(100), city VARCHAR(100) NOT NULL, region VARCHAR(100), postal_code VARCHAR(20), country_code CHAR(2) NOT NULL, UNIQUE KEY uq_order_address_type(order_id,address_type), FOREIGN KEY(order_id) REFERENCES orders(order_id));
CREATE TABLE order_items (order_item_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NULL, sku_snapshot VARCHAR(50) NOT NULL, product_name_snapshot VARCHAR(180) NOT NULL, variant_name_snapshot VARCHAR(160) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(12,2) NOT NULL, unit_cost_snapshot DECIMAL(12,2) NOT NULL, discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0, tax_rate_snapshot DECIMAL(7,4) NULL, tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0, line_total DECIMAL(12,2) NOT NULL, CHECK(quantity>0), FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(variant_id) REFERENCES product_variants(variant_id), KEY ix_order_items_variant(variant_id));
CREATE TABLE order_coupons (order_id BIGINT UNSIGNED NOT NULL, coupon_id BIGINT UNSIGNED NOT NULL, discount_amount DECIMAL(12,2) NOT NULL, PRIMARY KEY(order_id,coupon_id), FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(coupon_id) REFERENCES coupons(coupon_id));
CREATE TABLE coupon_redemptions (redemption_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, coupon_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NULL, order_id BIGINT UNSIGNED NOT NULL, redeemed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_coupon_redemption(coupon_id,order_id), KEY ix_coupon_customer_redemption(coupon_id,customer_id,redeemed_at), FOREIGN KEY(coupon_id) REFERENCES coupons(coupon_id), FOREIGN KEY(customer_id) REFERENCES customers(customer_id), FOREIGN KEY(order_id) REFERENCES orders(order_id), KEY ix_coupon_customer(coupon_id,customer_id));
CREATE TABLE payments (payment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, payment_method ENUM('card','bank_transfer','cash_on_delivery','wallet') NOT NULL, provider VARCHAR(60), payment_status ENUM('pending','authorized','captured','failed','partially_refunded','refunded') NOT NULL, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL, provider_reference VARCHAR(120), paid_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(order_id), KEY ix_payments_order_status(order_id,payment_status));
CREATE TABLE payment_transactions (transaction_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED NOT NULL, transaction_type ENUM('authorize','capture','void','refund','failure') NOT NULL, amount DECIMAL(12,2) NOT NULL, provider_transaction_id VARCHAR(120), transaction_status ENUM('pending','succeeded','failed') NOT NULL, idempotency_key VARCHAR(100) UNIQUE, response_code VARCHAR(60), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(payment_id) REFERENCES payments(payment_id));
CREATE TABLE shipments (shipment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, warehouse_id INT UNSIGNED NOT NULL, carrier VARCHAR(80), service_level VARCHAR(80), tracking_number VARCHAR(120), shipment_status ENUM('label_created','packed','in_transit','delivered','exception','returned') NOT NULL, shipping_cost DECIMAL(12,2) NOT NULL DEFAULT 0, shipped_at DATETIME NULL, delivered_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_carrier_tracking(carrier,tracking_number), FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(warehouse_id));
CREATE TABLE shipment_items (shipment_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, PRIMARY KEY(shipment_id,order_item_id), CHECK(quantity>0), FOREIGN KEY(shipment_id) REFERENCES shipments(shipment_id), FOREIGN KEY(order_item_id) REFERENCES order_items(order_item_id));
CREATE TABLE customer_returns (return_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, return_number VARCHAR(32) NOT NULL UNIQUE, order_id BIGINT UNSIGNED NOT NULL, requested_by_customer_id BIGINT UNSIGNED NULL, return_status ENUM('requested','approved','rejected','in_transit','received','refunded','closed') NOT NULL, reason_code ENUM('defective','wrong_item','not_as_described','changed_mind','damaged_shipping','other') NOT NULL, customer_comment VARCHAR(1000), resolution ENUM('refund','replacement','store_credit') NOT NULL, requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, approved_by_user_id BIGINT UNSIGNED NULL, received_at DATETIME NULL, FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(requested_by_customer_id) REFERENCES customers(customer_id), FOREIGN KEY(approved_by_user_id) REFERENCES app_users(user_id));
CREATE TABLE return_items (return_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, item_condition ENUM('unopened','opened','damaged') NOT NULL, refund_amount DECIMAL(12,2) NOT NULL DEFAULT 0, restockable BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(return_id,order_item_id), CHECK(quantity>0), FOREIGN KEY(return_id) REFERENCES returns(return_id), FOREIGN KEY(order_item_id) REFERENCES order_items(order_item_id));
CREATE TABLE reviews (review_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NULL, rating TINYINT UNSIGNED NOT NULL, title VARCHAR(160), review_text TEXT, review_status ENUM('pending','published','rejected') NOT NULL DEFAULT 'pending', moderated_by_user_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_review_customer_orderitem(customer_id,order_item_id), CHECK(rating BETWEEN 1 AND 5), FOREIGN KEY(product_id) REFERENCES products(product_id), FOREIGN KEY(customer_id) REFERENCES customers(customer_id), FOREIGN KEY(order_item_id) REFERENCES order_items(order_item_id), FOREIGN KEY(moderated_by_user_id) REFERENCES app_users(user_id));
CREATE TABLE purchase_orders (purchase_order_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, po_number VARCHAR(32) NOT NULL UNIQUE, supplier_id INT UNSIGNED NOT NULL, warehouse_id INT UNSIGNED NOT NULL, status ENUM('draft','submitted','partially_received','received','cancelled') NOT NULL DEFAULT 'draft', currency CHAR(3) NOT NULL DEFAULT 'USD', ordered_at DATETIME NULL, expected_at DATE NULL, created_by_user_id BIGINT UNSIGNED NULL, note VARCHAR(1000), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(warehouse_id), FOREIGN KEY(created_by_user_id) REFERENCES app_users(user_id));
CREATE TABLE purchase_order_items (purchase_order_item_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, purchase_order_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, quantity_ordered INT UNSIGNED NOT NULL, quantity_received INT UNSIGNED NOT NULL DEFAULT 0, unit_cost DECIMAL(12,2) NOT NULL, CHECK(quantity_ordered>0 AND quantity_received<=quantity_ordered), FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(purchase_order_id), FOREIGN KEY(variant_id) REFERENCES product_variants(variant_id));
CREATE TABLE wishlists (wishlist_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL DEFAULT 'Saved items', is_default BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE wishlist_items (wishlist_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, added_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(wishlist_id,variant_id), FOREIGN KEY(wishlist_id) REFERENCES wishlists(wishlist_id), FOREIGN KEY(variant_id) REFERENCES product_variants(variant_id));
CREATE TABLE inventory_reservations (reservation_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_item_id BIGINT UNSIGNED NOT NULL, warehouse_id INT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, reservation_status ENUM('active','released','fulfilled','expired') NOT NULL DEFAULT 'active', expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at DATETIME NULL, CHECK(quantity>0), FOREIGN KEY(order_item_id) REFERENCES order_items(order_item_id), FOREIGN KEY(warehouse_id,variant_id) REFERENCES inventory(warehouse_id,variant_id));
CREATE TABLE goods_receipts (receipt_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, receipt_number VARCHAR(32) NOT NULL UNIQUE, purchase_order_id BIGINT UNSIGNED NOT NULL, received_by_user_id BIGINT UNSIGNED NULL, received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, note VARCHAR(500), FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(purchase_order_id), FOREIGN KEY(received_by_user_id) REFERENCES app_users(user_id));
CREATE TABLE goods_receipt_items (receipt_id BIGINT UNSIGNED NOT NULL, purchase_order_item_id BIGINT UNSIGNED NOT NULL, quantity_received INT UNSIGNED NOT NULL, unit_cost DECIMAL(12,2) NOT NULL, PRIMARY KEY(receipt_id,purchase_order_item_id), CHECK(quantity_received>0), FOREIGN KEY(receipt_id) REFERENCES goods_receipts(receipt_id), FOREIGN KEY(purchase_order_item_id) REFERENCES purchase_order_items(purchase_order_item_id));
CREATE TABLE order_status_history (history_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, old_status VARCHAR(40), new_status VARCHAR(40) NOT NULL, status_type ENUM('order','payment','fulfillment') NOT NULL DEFAULT 'order', changed_by_user_id BIGINT UNSIGNED NULL, reason VARCHAR(500), changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(order_id), FOREIGN KEY(changed_by_user_id) REFERENCES app_users(user_id), KEY ix_order_history(order_id,changed_at));
CREATE TABLE payment_webhook_events (webhook_event_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(60) NOT NULL, provider_event_id VARCHAR(160) NOT NULL, event_type VARCHAR(100) NOT NULL, processing_status ENUM('received','processed','failed') NOT NULL DEFAULT 'received', payload JSON NOT NULL, received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at DATETIME NULL, error_message VARCHAR(1000), UNIQUE KEY uq_webhook_provider_event(provider,provider_event_id));
CREATE TABLE audit_logs (audit_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(80) NOT NULL, before_data JSON NULL, after_data JSON NULL, ip_address VARCHAR(45), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES app_users(user_id), KEY ix_audit_entity(entity_type,entity_id,created_at));


